// A producer client.
//
// Expensive to open and cheap to reuse: it holds connections to every
// broker, cached topic metadata and partition leadership. Open one and
// keep it for the lifetime of the workload. Opening one per request redoes
// metadata discovery every time and defeats batching, which is the whole
// reason Kafka producers are fast.
type Producer struct {
	handle *witRuntime.Handle
}

func (self *Producer) TakeHandle() int32 {
	return self.handle.Take()
}

func (self *Producer) SetHandle(handle int32) {
	self.handle.Set(handle)
}

func (self *Producer) Handle() int32 {
	return self.handle.Use()
}

func (self *Producer) Drop() {
	handle := self.handle.TakeOrNil()
	if handle != 0 {
		resourceDropProducer(handle)
	}
}

